const b = $json.body || {};
const pr = b.pull_request || {};
const repo = b.repository || {};
const accionesUtiles = ['opened', 'ready_for_review', 'synchronize'];
const salida = {
  accion: String(b.action || ''),
  titulo: String(pr.title || ''),
  descripcion: String(pr.body || '').slice(0, 2000),
  numero_pr: pr.number || 0,
  propietario: repo.owner && repo.owner.login ? repo.owner.login : '',
  repo: repo.name || '',
  autor: pr.user && pr.user.login ? pr.user.login : '',
  valido: Boolean(pr.number && repo.name && accionesUtiles.indexOf(String(b.action || '')) !== -1)
};
return { json: salida };

const origen = $('Validar evento de PR').item.json;
const fullDiff = String($json.diff || '');
if (!fullDiff.trim() || fullDiff.length > 20000) throw new Error('Review blocked: diff empty or exceeds reviewed context; split PR or review manually');
const diff = fullDiff;
const coverage = fullDiff.length > diff.length ? 'PARCIAL: diff truncado, prohibido recomendar aprobar.' : 'COMPLETA';
const sistema = [
  'Eres un revisor de pull requests senior. Escribes en español, con tono constructivo.',
  'Responde SOLO con JSON válido:',
  '{ "resumen": "...", "riesgos": ["..."], "preguntas": ["..."], "veredicto": "aprobar|revisar" }',
  'Si el diff está truncado, dilo en el resumen. No inventes código que no esté en el diff.'
].join('\n');
const peticion_ia = {
  model: 'claude-opus-5',
  max_tokens: 2048,
  system: sistema,
  messages: [
    { role: 'user', content: 'PR #' + origen.numero_pr + ': ' + origen.titulo + '\n\nDESCRIPCIÓN:\n' + origen.descripcion + '\n\nCOBERTURA: ' + coverage + '\n\nDIFF:\n' + diff }
  ]
};
return { json: { peticion_ia: peticion_ia } };

const bloques = $json.content || [];
const texto = bloques
  .filter(function (b) { return b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('\n');
let revision;
try {
  const inicio = texto.indexOf('{');
  const fin = texto.lastIndexOf('}');
  revision = JSON.parse(texto.slice(inicio, fin + 1));
  if(!revision || typeof revision.resumen!=='string' || !Array.isArray(revision.riesgos) || !Array.isArray(revision.preguntas)) throw new Error('invalid_review');
  revision.veredicto='revisar'; // automated analysis never approves merging
} catch (e) {
  revision = { resumen: texto.slice(0, 800), riesgos: [], preguntas: [], veredicto: 'revisar' };
}
const origen = $('Validar evento de PR').item.json;
const comentario = [
  'Resumen automático de la PR (asistente IA, no sustituye la revisión humana):',
  '',
  revision.resumen,
  '',
  'Riesgos detectados:',
  (revision.riesgos || []).map(function (r) { return '- ' + r; }).join('\n') || '- ninguno detectado',
  '',
  'Preguntas para el autor:',
  (revision.preguntas || []).map(function (p) { return '- ' + p; }).join('\n') || '- ninguna',
  '',
  'Sugerencia: ' + revision.veredicto
].join('\n');
const salida = {
  propietario: origen.propietario,
  repo: origen.repo,
  numero_pr: origen.numero_pr,
  titulo: origen.titulo,
  autor: origen.autor,
  veredicto: revision.veredicto,
  comentario: comentario,
  revisado_en: new Date().toISOString()
};
return { json: salida };
